cp = configparser.ConfigParser(inline_comment_prefixes=(';', '#'))
cp.read('/app/config/settings.ini')

DROP = {('server', 'legacy_mode'), ('cache', 'legacy_keys')}

def convert(k, v):
    if k == 'timeout':
        ms = float(v) * 1000
        return 'timeout_ms', int(ms) if ms.is_integer() else ms
    if v.lower() in ('yes', 'no'):
        return k, v.lower() == 'yes'
    try:
        return k, int(v)
    except ValueError:
        return k, v

out = {'schema_version': 2}
for sec in cp.sections():
    obj = {}
    for k, v in cp.items(sec):
        if (sec, k) in DROP:
            continue
        k2, v2 = convert(k, v)
        obj[k2] = v2
    out[sec] = obj

with open('/app/config/settings.json', 'w') as f:
    json.dump(out, f, indent=2)
    f.write('\n')
print(open('/app/config/settings.json').read())"}

