import json, re
from pathlib import Path


def parse_scalar(s):
    s = s.strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "'\"":
        return s[1:-1]
    if s == "true":
        return True
    if s == "false":
        return False
    if re.fullmatch(r"-?\d+", s):
        return int(s)
    return s


def strip_comment(line):
    out, quote = "", None
    for ch in line:
        if quote:
            out += ch
            if ch == quote:
                quote = None
        elif ch in "'\"":
            quote = ch
            out += ch
        elif ch == "#":
            break
        else:
            out += ch
    return out.rstrip()


def indent_of(raw):
    return len(raw) - len(raw.lstrip())


def parse_block(lines, i, indent):
    """Parse the block starting at lines[i]; returns (node, next_i)."""
    seq = lines[i].lstrip().startswith("- ")
    if seq:
        items = []
        while i < len(lines):
            raw = strip_comment(lines[i])
            if not raw.strip():
                i += 1
                continue
