{"content": """"Minimal pure-Python YAML subset parser (safe_load only).

Supports exactly what config/services.yaml uses:
block mappings/sequences, &anchors, <<: *merge keys, single/double-quoted
scalars, flow mappings {k: v, ...}, ints/bools/null, and # comments.
It exists only because no YAML library is installable in this sandbox.
"""
import re


class SafeLoader:
    def __init__(self, text):
        self.lines = []
        for raw in text.splitlines():
            if raw.lstrip().startswith("#"):
                continue
            self.lines.append(self._strip_comment(raw))
        self.anchors = {}

    @staticmethod
    def _strip_comment(line):
        out = []
        quote = None
        for ch in line:
            if quote:
                out.append(ch)
                if ch == quote:
                    quote = None
            else:
                if ch in ("'", '"'):
                    quote = ch
                    out.append(ch)
                elif ch == "#":
                    break
                else:
                    out.append(ch)
        return out and "".join(out).rstrip() or ""

    def load(self):
        value, i = self._parse_block(0, 0)
        return value

    def _parse_block(self, i, indent):
        if i < len(self.lines) and self.lines[i].lstrip().startswith("- "):
            return self._parse_seq(i, indent)
        return self._parse_map(i, indent)

    def _parse_seq(self, i, indent):
        seq = []
        while i < len(self.lines):
            line = self.lines[i]
            cur = len(line) - len(line.lstrip())
            if cur < indent or not line.lstrip():
                break
            body = line.lstrip()
            if not body.startswith("- "):
                break
            item = body[2:]
            if item == "":
                i += 1
                val, i = self._parse_block(i, indent + 1)
                seq.append(val)
            elif ":" in self._split_kv(item)[0]:
                # inline first key of a mapping item; treat rest as that map
                m = self._parse_map_from_first(i, cur + 2)
                seq.append(m[0])
                i = m[1]
            else:
                seq.append(self._scalar(item))
                i += 1
        return seq, i

    def _parse_map_from_first(self, i, key_indent):
        # rewrite the "- key: value" line as a normal map line at key_indent
        line = self.lines[i]
        body = line.lstrip()[2:]
        saved = self.lines[i]
        self.lines[i] = " " * key_indent + body
        val, j = self._parse_map(i, key_indent)
        self.lines[i] = saved  # not reused, but restore for safety
        return val, j

    @staticmethod
    def _split_kv(text):
        quote = None
        for pos, ch in enumerate(text):
            if quote:
                if ch == quote:
                    quote = None
            elif ch in ("'", '"'):
                quote = ch
            elif ch == ":" and (pos + 1 == len(text) or text[pos + 1] in " \t"):
                return text[:pos].strip(), text[pos + 1:].strip()
        return None, None

    def _parse_map(self, i, indent):
        mapping = {}
        merges = []
        while i < len(self.lines):
            line = self.lines[i]
            if not line.strip():
                i += 1
                continue
            cur = len(line) - len(line.lstrip())
            if cur != indent:
                break
            key, rest = self._split_kv(line.strip())
            if key is None:
                break
            if key == "<<":
                merges.append(self._scalar(rest))
                i += 1
                continue
            anchor = None
            if rest.startswith("&"):
                parts = rest.split(None, 1)
                anchor = parts[0][1:]
                rest = parts[1] if len(parts) > 1 else ""
            if rest == "":
                i += 1
                # nested block: next non-empty line's indent decides
                j = i
                while j < len(self.lines) and not self.lines[j].strip():
                    j += 1
                if j < len(self.lines) and len(self.lines[j]) - len(self.lines[j].lstrip()) > indent:
                    val, i = self._parse_block(i, len(self.lines[j]) - len(self.lines[j].lstrip()))
                else:
                    val = None
            else:
                val = self._scalar(rest)
                i += 1
            if anchor:
                self.anchors[anchor] = val
            mapping[self._key(key)] = val
        for m in reversed(merges):
            mapping = {**m, **mapping}
        return mapping, i

    @staticmethod
    def _key(text):
        if len(text) >= 2 and text[0] == text[-1] and text[0] in ("'", '"'):
            return text[1:-1]
        return text

    def _scalar(self, text):
        text = text.strip()
        if text.startswith("*"):
            return self.anchors[text[1:]]
        if text.startswith("{") and text.endswith("}"):
            out = {}
            body = text[1:-1].strip()
            if not body:
                return out
            for part in self._split_flow(body):
                k, v = self._split_kv(part)
                out[self._key(k)] = self._scalar(v)
            return out
        if text.startswith("[") and text.endswith("]"):
            return [self._scalar(p) for p in self._split_flow(text[1:-1].strip()) if p]
        if len(text) >= 2 and text[0] == text[-1] and text[0] in ("'", '"'):
            return text[1:-1]
        if text == "true":
            return True
        if text == "false":
            return False
        if text in ("null", "~", ""):
            return None
        if re.fullmatch(r"-?\d+", text):
            return int(text)
        if re.fullmatch(r"-?\d+\.\d+", text):
            return float(text)
        return text

    @staticmethod
    def _split_flow(body):
        parts, depth, quote, cur = [], 0, None, []
        for ch in body:
            if quote:
                cur.append(ch)
                if ch == quote:
                    quote = None
            elif ch in ("'", '"'):
                quote = ch
                cur.append(ch)
            elif ch in "{[":
                depth += 1
                cur.append(ch)
            elif ch in "}]":
                depth -= 1
                cur.append(ch)
            elif ch == "," and depth == 0:
                parts.append("".join(cur).strip())
                cur = []
            else:
                cur.append(ch)
        if cur and "".join(cur).strip():
            parts.append("".join(cur).strip())
        return parts


def safe_load(text):
    return SafeLoader(text).load()
