{"content": """"Fallback renderer: parses config/services.yaml without PyYAML (not installed,
no network) using a minimal YAML subset parser that covers this file's features
(anchors, merge keys, comments, quoting, flow mappings), then applies the exact
logic from tools/render.py to produce out/services.json.
"""
import json
import re
from pathlib import Path

# --- minimal YAML subset parser -------------------------------------------

def parse_scalar(s):
    s = s.strip()
    if s == "" or s == "~" or s == "null":
        return None
    if len(s) >= 2 and s[0] == s[-1] and s[0] in ("'", '"'):
        body = s[1:-1]
        if s[0] == '"':
            body = body.replace('\\"', '"').replace("\\\\", "\\")
        else:
            body = body.replace("''", "'")
        return body
    if s == "true":
        return True
    if s == "false":
        return False
    if re.fullmatch(r"-?\d+", s):
        return int(s)
    if re.fullmatch(r"-?\d+\.\d+", s):
        return float(s)
    return s


def strip_comment(line):
    # remove trailing comments outside quotes
    out, quote = "", None
    i = 0
    while i < len(line):
        c = line[i]
        if quote:
            if quote == "'" and c == "'" and i + 1 < len(line) and line[i+1] == "'":
                out += "''"; i += 2; continue
            if c == quote:
                quote = None
            out += c
        else:
            if c in ("'", '"'):
                quote = c; out += c
            elif c == "#" and (i == 0 or line[i-1] in " \t"):
                break
            else:
                out += c
        i += 1
    return out.rstrip()


def parse_flow(s):
    # parse a flow mapping like {A: 1, B: "x"} (no nested flow in this file)
    assert s.startswith("{") and s.endswith("}")
    body = s[1:-1]
    items, cur, quote = [], "", None
    for c in body:
        if quote:
            cur += c
            if c == quote:
                quote = None
        elif c in ("'", '"'):
            quote = c; cur += c
        elif c == ",":
            items.append(cur); cur = ""
        else:
            cur += c
    if cur.strip():
        items.append(cur)
    d = {}
    for it in items:
        k, v = it.split(":", 1)
        d[parse_scalar(k)] = parse_scalar(v)
    return d


def parse_block(lines):
    """Parse a block mapping into a dict, handling anchors, merge keys, comments."""
    anchors = {}
    root = {}
    stack = [(-1, root)]  # (indent, dict)

    def resolve(node, seen=()):
        # expand merge keys after full parse
        if isinstance(node, dict):
            merged = {}
            for k in list(node):
                if k == "<<":
                    src = anchors[node[k].lstrip("*")] if isinstance(node[k], str) else node[k]
                    assert isinstance(src, dict)
                    merged.update(resolve(src))
            for k in list(node):
                if k != "<<":
                    merged[k] = resolve(node[k])
            return merged
        return node

    for raw in lines:
        line = strip_comment(raw.rstrip("\n"))
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        s = line.strip()
        if s.startswith("- ") or s == "-":
            # new list item
            while stack and stack[-1][0] >= indent and not isinstance(stack[-1][1], list):
                stack.pop()
            if not isinstance(stack[-1][1], list):
                # find nearest list on stack at this indent
                pass
            item = {}
            stack[-1][1].append(item)
            stack.append((indent, item))
            s = s[1:].strip()
            if not s:
                continue
            if s.startswith("- "):
                s = s  # nested weirdness not expected
        # key: value
        m = re.match(r'([^:]+):(?:\s+(.*))?$', s)
        assert m, f"unparsed line: {s!r}"
        key = parse_scalar(m.group(1))
        val = m.group(2)
        target = stack[-1][1]
        if val is None or val == "":
            # nested block follows
            child = {}
            target[key] = child
            stack.append((indent, child))
            continue
        if val.startswith("&"):
            name, _, rest = val.partition(" ")
            anchors[name[1:]] = None  # placeholder, filled below
            anchor_name = name[1:]
            val = rest.strip()
            if val.startswith("{"):
                node = parse_flow(val)
            elif val == "":
                node = {}  # block mapping follows; we will fill it
            else:
                node = parse_scalar(val)
            anchors[anchor_name] = node
            target[key] = node
            if isinstance(node, dict) and val == "":
                stack.append((indent, node))
            continue
        if val.startswith("{"):
            target[key] = parse_flow(val)
            continue
        target[key] = parse_scalar(val)

    return resolve(root)


def parse_list_items(lines):
    """Parse the services: list with anchors/merge keys."""
    items = []
    anchors = {}
    cur = None
    for raw in lines:
        line = strip_comment(raw.rstrip("\n"))
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        s = line.strip()
        if s.startswith("- "):
            cur = {}
            items.append(cur)
            s = s[2:].strip()
            if not s:
                continue
            # fall through to handle "- name: x" on same line
            m = re.match(r'([^:]+):\s*(.*)$', s)
            key = parse_scalar(m.group(1))
            val = m.group(2)
            if val == "":
                cur[key] = {}
                cur = cur[key]
                continue
            cur[key] = val
            continue
        m = re.match(r'([^:]+):\s*(.*)$', s)
        assert m, f"unparsed: {s!r}"
        key = parse_scalar(m.group(1))
        val = m.group(2)
        if key == "<<":
            cur[key] = val
        elif val == "":
            child = {}
            cur[key] = child
            cur = child
        elif val.startswith("{"):
            cur[key] = parse_flow(val)
        elif val.startswith("&"):
            pass
        else:
            cur[key] = parse_scalar(val)

    # expand merge keys
    out = []
    for it in items:
        merged = {}
        for k in list(it):
            if k == "<<":
                src = it[k].lstrip("*")
                # anchors were collected from the defaults block; re-read
                merged.update(ANCHORS[src])
            else:
                merged[k] = it[k]
        out.append(merged)
    return out


def parse_document(text):
    lines = text.splitlines()
    # find "defaults:" block and "services:" block
    di = next(i for i, l in enumerate(lines) if l.startswith("defaults:"))
    si = next(i for i, l in enumerate(lines) if l.startswith("services:"))
    defaults_lines = lines[di+1:si]
    services_lines = lines[si+1:]

    # parse defaults block (a mapping with an anchor)
    d = {}
    anchors = {}
    cur = None
    for raw in defaults_lines:
        line = strip_comment(raw.rstrip("\n"))
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        s = line.strip()
        if indent == 0 and s.startswith("defaults:"):
            rest = s[len("defaults:"):].strip()
            if rest.startswith("&"):
                anchors[rest[1:]] = d
            cur = d
            continue
        m = re.match(r'([^:]+):\s*(.*)$', s)
        key = parse_scalar(m.group(1))
        val = m.group(2)
        if val == "":
            child = {}
            cur[key] = child
            cur = child
        elif val.startswith("{"):
            cur[key] = parse_flow(val)
        else:
            cur[key] = parse_scalar(val)

    global ANCHORS
    ANCHORS = anchors
    services = parse_list_items(services_lines)
    return {"defaults": d, "services": services}


# --- exact render logic from tools/render.py -------------------------------

def render(doc: dict) -> dict:
    defaults = doc["defaults"]
    out = []
    for svc in doc["services"]:
        if not svc.get("enabled", True):
            continue
        env = {**defaults["env"], **svc.get("env", {})}
        out.append(
            {
                "name": svc["name"],
                "url": f"http://{svc['host']}:{svc['port']}{svc['health_path']}",
                "replicas": svc["replicas"],
                "env": dict(sorted(env.items())),
            }
        )
    return {"services": sorted(out, key=lambda s: s["name"])}


if __name__ == "__main__":
    doc = parse_document(Path("config/services.yaml").read_text())
    import sys
    if "--show-doc" in sys.argv:
        print(json.dumps(doc, indent=2))
    Path("out").mkdir(exist_ok=True)
    Path("out/services.json").write_text(json.dumps(render(doc), indent=2) + "\n")
    print("rendered out/services.json")
