{"content": """"Minimal yaml.safe_load shim backed by ruamel.yaml (safe mode, pure parser).

Matches PyYAML.safe_load semantics for plain YAML docs, including merge keys (<<).
"""
import io

from ruamel.yaml import YAML

_y = YAML(typ="safe", pure=True)


def safe_load(stream):
    return _y.load(io.StringIO(stream))


__all__ = ["safe_load"]
