{"content": """"Minimal yaml shim: safe_load for block maps/seqs, anchors (&name on a
block map value), merge keys (<<: *name), flow maps, comments, quotes.
Scope: sufficient for /app/config/services.yaml only."""


def _strip_comment(s):
    out, q = "", None
    for ch in s:
        if q:
            out += ch
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
            out += ch
        elif ch == "#":
            break
        else:
            out += ch
    return out.rstrip()


def _scalar(s):
    s = s.strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "\"'":
        return s[1:-1]
    if s == "true":
        return True
    if s == "false":
        return False
    if s in ("null", "~", ""):
        return None
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    return s


def _split_flow(s):
    parts, cur, q = [], "", None
    for ch in s:
        if q:
            cur += ch
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
            cur += ch
        elif ch == ",":
            parts.append(cur)
            cur = ""
        else:
            cur += ch
    if cur.strip():
        parts.append(cur)
    return parts


def _parse_flow(s):
    result = {}
    for part in _split_flow(s.strip()[1:-1]):
        k, _, v = part.partition(":")
        result[_scalar(k)] = _scalar(v)
    return result


def _split_key(s):
    """Split 'key: rest' on the first colon that ends the key."""
    idx, q = 0, None
    while idx < len(s):
        ch = s[idx]
        if q:
            if ch == q:
                q = None
        elif ch in "\"'":
            q = ch
        elif ch == ":":
            if idx + 1 == len(s) or s[idx + 1] in " \t":
                return s[:idx], s[idx + 1:]
        idx += 1
    return None, None


class Parser:
    def __init__(self, lines):
        self.lines = lines
        self.anchors = {}

    def parse(self, i, indent):
        """Parse block node at self.lines[i] with given indent -> (value, next_i)."""
        # skip blanks
        while i < len(self.lines) and not self.lines[i].strip():
            i += 1
        if i >= len(self.lines):
            return None, i
        line = self.lines[i]
        cur = len(line) - len(line.lstrip())
        if cur < indent:
            return None, i
        if line.lstrip().startswith("- "):
            return self.parse_seq(i, cur)
        if line.lstrip() == "-":
            return self.parse_seq(i, cur)
        return self.parse_map(i, cur)

    def parse_seq(self, i, indent):
        seq = []
        while i < len(self.lines):
            line = self.lines[i]
            if not line.strip():
                i += 1
                continue
            cur = len(line) - len(line.lstrip())
            if cur != indent or not line.lstrip().startswith("-"):
                break
            content = line.lstrip()[1:].lstrip()
            if content:
                # inline first key of a mapping, or a scalar
                if _split_key(content)[0] is not None:
                    # rewrite line as if key started at its own position
                    pos = line.index(content)
                    sub = self.lines[:i] + [" " * pos + content] + self.lines[i + 1:]
                    saved = self.lines
                    self.lines = sub
                    val, j = self.parse_map(i, pos)
                    self.lines = saved
                    seq.append(val)
                    i = j
                elif content.startswith("{"):
                    seq.append(_parse_flow(content))
                    i += 1
                else:
                    seq.append(_scalar(content))
                    i += 1
            else:
                val, i = self.parse(i + 1, indent + 1)
                seq.append(val)
        return seq, i

    def parse_map(self, i, indent):
        mapping = {}
        while i < len(self.lines):
            line = self.lines[i]
            if not line.strip():
                i += 1
                continue
            cur = len(line) - len(line.lstrip())
            if cur != indent or line.lstrip().startswith("-"):
                break
            s = _strip_comment(line).strip()
            key_s, rest = _split_key(s)
            if key_s is None:
                i += 1
                continue
            key = _scalar(key_s)
            rest = rest.strip()
            # anchor tag on value: '&name'
            anchor = None
            if rest.startswith("&"):
                parts = rest.split(None, 1)
                anchor = parts[0][1:]
                rest = parts[1].strip() if len(parts) > 1 else ""
            if key == "<<":
                name = rest[1:]
                mapping.update(self.anchors.get(name, {}))
                i += 1
                continue
            if rest.startswith("{"):
                val = _parse_flow(rest)
                i += 1
            elif rest == "":
                # nested block or null
                j = i + 1
                while j < len(self.lines) and not self.lines[j].strip():
                    j += 1
                if j < len(self.lines):
                    child = len(self.lines[j]) - len(self.lines[j].lstrip())
                    if child > indent:
                        val, i = self.parse(j, child)
                    else:
                        val, i = None, i + 1
                else:
                    val, i = None, j
            else:
                val = _scalar(rest)
                i += 1
            if anchor is not None:
                self.anchors[anchor] = val
            mapping[key] = val
        return mapping, i


def safe_load(text):
    lines = [_strip_comment(l).rstrip() for l in text.splitlines()]
    p = Parser(lines)
    val, _ = p.parse(0, 0)
    return val
