The shim parses the subset of YAML used by config/services.yaml: block mappings,
nested mappings via indentation, &anchor / *alias, merge key `<<: *alias`,
flow mappings {k: v, ...}, ints, booleans, single/double-quoted and plain scalars,
and trailing comments. render.py's render() logic is executed verbatim.
"""
import json
import sys
from pathlib import Path


def strip_comment(line: str) -> str:
    out = []
    in_s = in_d = False
    for i, ch in enumerate(line):
        if ch == "'" and not in_d:
            in_s = not in_s
        elif ch == '"' and not in_s:
            in_d = not in_d
        elif ch == "#" and not in_s and not in_d and (i == 0 or line[i - 1] in " \t"):
            break
        out.append(ch)
    return "".join(out).rstrip()


def parse_scalar(s: str):
    s = s.strip()
    if s.startswith("{") and s.endswith("}"):
        inner = s[1:-1].strip()
        d = {}
        if inner:
            for part in split_top(inner):
                k, _, v = part.partition(":")
                d[parse_scalar(k)] = parse_scalar(v)
        return d
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "'\"":
        return s[1:-1]
    if s in ("true", "True"):
        return True
    if s in ("false", "False"):
        return False
    if s in ("null", "~", ""):
        return None
    try:
        return int(s)
    except ValueError:
        return s


def split_top(s: str):
    parts, depth, cur = [], 0, []
    in_s = in_d = False
    for ch in s:
        if ch == "'" and not in_d:
            in_s = not in_s
        elif ch == '"' and not in_s:
            in_d = not in_d
        if ch == "{" and not in_s and not in_d:
            depth += 1
        if ch == "}" and not in_s and not in_d:
            depth -= 1
        if ch == "," and depth == 0 and not in_s and not in_d:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    if cur:
        parts.append("".join(cur))
    return parts


def parse_block(lines, anchors):
    """Parse a block mapping; lines is a list of (indent, text). Returns dict, next index."""
    result = {}
    i = 0
    while i < len(lines):
        indent, text = lines[i]
        key, _, rest = text.partition(":")
        key = key.strip()
        rest = rest.strip()
        if rest.startswith("&"):  # value anchor on same line, e.g. `defaults: &defaults`
            anchor_name = rest[1:].strip()
            i += 1
            sub, i = parse_block(lines[i:], anchors)
            anchors[anchor_name] = sub
            result[key] = sub
            continue
        if rest.startswith("*"):  # alias (used for merge key)
            result[key] = anchors[rest[1:].strip()]
            i += 1
            continue
        if rest == "":
            # nested block (list or mapping) at deeper indent
            i += 1
            children = []
            while i < len(lines) and lines[i][0] > indent:
                children.append(lines[i])
                i += 1
            if not children:
                result[key] = None
            elif children[0][1].startswith("- ") or children[0][1] == "-":
                # sequence of mappings: collect items and merge adjacent deeper lines
                items = []
                j = 0
                while j < len(children):
                    cind, ctext = children[j]
                    item_text = ctext[1:].strip()
                    item_lines = [(cind + 2, item_text)] if item_text else []
                    j += 1
                    while j < len(children) and children[j][0] > cind:
                        item_lines.append(children[j])
                        j += 1
                    item, _ = parse_block(item_lines, anchors)
                    items.append(item)
                result[key] = items
            else:
                sub, _ = parse_block(children, anchors)
                result[key] = sub
            continue
        result[key] = parse_scalar(rest)
        i += 1
    return result, i


def resolve_merge(node):
    if isinstance(node, dict):
        merged = {}
        merge_src = None
        for k, v in node.items():
