        out, quote = "", None
        for ch in body:
            if quote:
                out += ch
                if ch == quote:
                    quote = None
            elif ch in "'\"":
                quote = ch
                out += ch
            elif ch == "#":
                break
            else:
                out += ch
        if out.strip():
            lines.append((len(indent), out.strip()))
        else:
            lines.append((len(indent), ""))
    anchors = {}

    def parse_block(i, indent):
        """Parse mapping starting at line i with given indent."""
        result = {}
