            ind, body = lines[i]
            if ind < indent or body == "":
                break
            if ind > indent:
                raise ValueError(f"unexpected indent at line {i+1}")
            if body.startswith("- "):
                raise ValueError("sequence not expected here")
            key, _, rest = body.partition(":")
            key = key.strip()
            rest = rest.strip()
            if rest.startswith("&"):
                # anchor definition on mapping value -> block
                name, _, rest2 = rest.partition(" ")
                rest = rest2.strip()
                val, i = parse_block(i + 1, indent + 2)
                anchors[name[1:]] = val
                result[key] = val
                continue
            if rest == "":
                # nested block or empty
                if i + 1 < len(lines) and lines[i + 1][1].startswith("- "):
                    # sequence
