    s = s.strip()
    if s.startswith(("'", '"')) and s.endswith(s[0]) and len(s) >= 2:
        return s[1:-1]
    if s == "true":
        return True
    if s == "false":
        return False
    if s.lstrip("-").isdigit():
        return int(s)
    return s


def _flow_map(s):
    s = s.strip()
    assert s.startswith("{") and s.endswith("}")
    body = s[1:-1].strip()
    out = {}
    if not body:
        return out
    for part in body.split(","):
        k, v = part.split(":", 1)
        out[_scalar(k)] = _scalar(v)
    return out


