    s = s.strip()
    if not s:
        return None
    if (s[0] == '"' and s[-1] == '"') or (s[0] == "'" and s[-1] == "'"):
        return s[1:-1]
    if s == "{}":
        return {}
    if s.startswith("{") and s.endswith("}"):
        inner = s[1:-1]
        result = {}
        # split on commas outside quotes
        parts, buf, quote = [], "", None
        for c in inner:
            if quote:
                buf += c
                if c == quote:
                    quote = None
            elif c in "\"'":
                quote = c
                buf += c
            elif c == ",":
                parts.append(buf)
                buf = ""
            else:
                buf += c
        if buf.strip():
            parts.append(buf)
        for part in parts:
            k, _, v = part.partition(":")
            result[_parse_scalar(k)] = _parse_scalar(v)
        return result
    low = s.lower()
    if s.isdigit():
        return int(s)
    if low in ("true", "yes", "on"):
        return True
    if low in ("false", "no", "off"):
        return False
    if low in ("null", "~"):
        return None
    return s


