Reads one transaction from src/INPUT.DAT, validates buyer/seller/book,
then updates data/ACCOUNTS.DAT, data/BOOKS.DAT and appends to
data/TRANSACTIONS.DAT using fixed-length records (as GnuCOBOL record
sequential files): accounts 34 bytes, books 28 bytes, transactions 22
bytes, input 22 bytes. Run from /app.
"""

from pathlib import Path

REC_ACC = 34
REC_BOOK = 28
REC_TRANS = 22
REC_IN = 22


def read_records(path, size):
    data = Path(path).read_bytes()
    return [data[i:i + size] for i in range(0, len(data), size)]


def write_records(path, records):
    Path(path).write_bytes(b"".join(records))


def field(rec, start, end):
    return rec[start:end].decode("latin-1")


def numeric(text):
    t = text.strip()
    if not t:
        return 0
    try:
        return int(t)
    except ValueError:
        # Non-numeric garbage: take leading digit run, else 0
        digits = ""
        for ch in t:
            if ch.isdigit():
                digits += ch
            else:
                break
        return int(digits) if digits else 0


def main():
    input_rec = Path("src/INPUT.DAT").read_bytes()
    if not input_rec:
        print("Error: Input file is empty")
        return
    input_rec = (input_rec + b" " * REC_IN)[:REC_IN]
    buyer = input_rec[0:4].decode("latin-1")
    seller = input_rec[4:8].decode("latin-1")
    book_id = input_rec[8:12].decode("latin-1")
    amount = numeric(field(input_rec, 12, 22))

    # VALIDATE-USERS-AND-BOOK
    buyer_found = seller_found = book_found = valid_owner = False
    for rec in read_records("data/ACCOUNTS.DAT", REC_ACC):
        if field(rec, 0, 4) == buyer:
            buyer_found = True
        if field(rec, 0, 4) == seller:
            seller_found = True
    for rec in read_records("data/BOOKS.DAT", REC_BOOK):
        if field(rec, 0, 4) == book_id:
            book_found = True
            if field(rec, 24, 28) == seller:
                valid_owner = True
    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        return

    # PROCESS-TRANSACTION
    accounts = read_records("data/ACCOUNTS.DAT", REC_ACC)
    for rec in accounts:
        acc_id = field(rec, 0, 4)
        if acc_id == buyer:
            bal = numeric(field(rec, 24, 34)) - amount
