        if acc_id == seller:
            bal = numeric(field(rec, 24, 34)) + amount
            rec[:34] = rec[0:24] + f"{bal:010d}".encode()
    write_records("data/ACCOUNTS.DAT", accounts)

    books = read_records("data/BOOKS.DAT", REC_BOOK)
    for rec in books:
        if field(rec, 0, 4) == book_id:
            rec[:28] = rec[0:24] + buyer.encode("latin-1")
    write_records("data/BOOKS.DAT", books)

    trans = read_records("data/TRANSACTIONS.DAT", REC_TRANS)
    trans.append(
        book_id.encode("latin-1")
        + f"{amount:010d}".encode()
        + seller.encode("latin-1")
        + buyer.encode("latin-1")
    )
    write_records("data/TRANSACTIONS.DAT", trans)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
