{"content": "#!/usr/bin/env python3
"""Python re-implementation of program.cbl (BOOKFORUM).

Replicates GnuCOBOL 3.2 record-sequential file handling and PICTURE semantics:
- Files are fixed-length binary records with no separators.
- Reads that hit a short final record are padded with spaces.
- Invalid (non-digit) characters in a numeric display field are treated as 0.
- Unsigned PIC 9(n) results are stored as the magnitude's low-order n digits.
"""

import sys

ACCOUNTS = "data/ACCOUNTS.DAT"
BOOKS = "data/BOOKS.DAT"
TRANSACTIONS = "data/TRANSACTIONS.DAT"
INPUT = "src/INPUT.DAT"

ACC_REC = 4 + 20 + 10   # ACCOUNT-ID, ACCOUNT-NAME, ACCOUNT-BALANCE 9(10)
BOOK_REC = 4 + 20 + 4   # BOOK-ID, BOOK-TITLE, BOOK-OWNER
TRANS_REC = 4 + 10 + 4 + 4  # TRANS-BOOK, TRANS-AMOUNT 9(10), SELLER, BUYER
INPUT_REC = 4 + 4 + 4 + 10  # BUYER, SELLER, BOOK, AMOUNT 9(10)


def num(field: str) -> int:
    """Numeric display field -> int; invalid chars (spaces etc.) count as 0."""
    return int("".join(c if c.isdigit() else "0" for c in field) or "0")


def pic9(value: int, width: int) -> str:
    """Store into unsigned PIC 9(n): magnitude, low-order n digits."""
    return str(abs(value) % (10 ** width)).zfill(width)


def read_records(path: str, rec_len: int) -> list[str]:
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except FileNotFoundError:
        return []
    records = []
    for i in range(0, len(raw), rec_len):
        chunk = raw[i:i + rec_len].decode("latin-1")
        records.append(chunk.ljust(rec_len))
    return records


def write_records(path: str, rec_len: int, records: list[str]) -> None:
    with open(path, "wb") as f:
        for rec in records:
            f.write(rec.encode("latin-1"))


def main() -> None:
    # MAIN-PARA: read the single input record
    try:
        with open(INPUT, "rb") as f:
            raw = f.read(INPUT_REC)
    except FileNotFoundError:
        raw = b""
    if not raw:
        print("Error: Input file is empty")
        sys.exit(0)
    rec = raw.decode("latin-1").ljust(INPUT_REC)
    buyer_id = rec[0:4]
    seller_id = rec[4:8]
    book_id = rec[8:12]
    amount = num(rec[12:22])  # PIC 9(10) -> 9(10)V99: value with .00 decimals

    # VALIDATE-USERS-AND-BOOK
    buyer_found = seller_found = book_found = valid_owner = False
    for acc in read_records(ACCOUNTS, ACC_REC):
        if acc[0:4] == buyer_id:
            buyer_found = True
        if acc[0:4] == seller_id:
            seller_found = True
    for book in read_records(BOOKS, BOOK_REC):
        if book[0:4] == book_id:
            book_found = True
            if book[24:28] == seller_id:
                valid_owner = True
    print(" ")

    if not (buyer_found and seller_found and book_found and valid_owner):
        print("Transaction failed due to validation errors")
        sys.exit(0)

    # PROCESS-TRANSACTION
    accounts = read_records(ACCOUNTS, ACC_REC)
    for i, acc in enumerate(accounts):
        if acc[0:4] == buyer_id:
            balance = num(acc[24:34]) - amount
            accounts[i] = acc[0:24] + pic9(balance, 10)
        if acc[0:4] == seller_id:
            balance = num(acc[24:34]) + amount
            accounts[i] = acc[0:24] + pic9(balance, 10)
    write_records(ACCOUNTS, ACC_REC, accounts)

    books = read_records(BOOKS, BOOK_REC)
    for i, book in enumerate(books):
        if book[0:4] == book_id:
            books[i] = book[0:24] + buyer_id
    write_records(BOOKS, BOOK_REC, books)

    trans = read_records(TRANSACTIONS, TRANS_REC)
    trans.append(book_id + pic9(amount, 10) + seller_id + buyer_id)
    write_records(TRANSACTIONS, TRANS_REC, trans)

    print("Transaction completed successfully")


if __name__ == "__main__":
    main()
