from collections import Counter
from datetime import date
from pathlib import Path

TODAY = date(2025, 8, 12)
SEVS = ("ERROR", "WARNING", "INFO")
pat = re.compile(r"\[(ERROR|WARNING|INFO)\]")

counts = {"total": Counter(), "today": Counter(), "last_7_days": Counter(),
          "last_30_days": Counter(), "month_to_date": Counter()}

for f in Path("/app/logs").glob("*.log"):
    d = date.fromisoformat(f.name[:10])
    periods = ["total"]
    if d == TODAY:
        periods += ["today", "last_7_days", "last_30_days", "month_to_date"]
    else:
        if TODAY - d < __import__("datetime").timedelta(days=7):
            periods.append("last_7_days")
        if TODAY - d < __import__("datetime").timedelta(days=30):
            periods.append("last_30_days")
        if (d.year, d.month) == (TODAY.year, TODAY.month):
            periods.append("month_to_date")
    c = Counter(m.group(1) for line in f.read_text().splitlines()
                if (m := pat.search(line)))
    for p in periods:
        counts[p].update(c)

rows = ["period,severity,count"]
for p in ("today", "last_7_days", "last_30_days", "month_to_date", "total"):
    for s in SEVS:
        rows.append(f"{p},{s},{counts[p][s]}")
Path("/app/summary.csv").write_text("\n".join(rows) + "\n")
