for path in sorted(glob.glob('/app/logs/*.log')):
    d = date.fromisoformat(os.path.basename(path).split('_')[0])
    with open(path) as f:
        for line in f:
            m = pat.search(line)
            if m:
                per_day[d][m.group(1)] += 1

def count(start, end):
    c = collections.Counter()
    for d, cnt in per_day.items():
        if start <= d <= end:
            c += cnt
    return c

periods = {
    'today': count(today, today),
    'last_7_days': count(today - timedelta(days=6), today),
    'last_30_days': count(today - timedelta(days=29), today),
    'month_to_date': count(today.replace(day=1), today),
