today = date(2025, 8, 12)
from datetime import timedelta
d7 = today - timedelta(days=6)
d30 = today - timedelta(days=29)
month_start = today.replace(day=1)

levels = ["ERROR", "WARNING", "INFO"]
pat = re.compile(r"\[(ERROR|WARNING|INFO)\]")

counts = {p: {s: 0 for s in levels} for p in
          ["today", "last_7_days", "last_30_days", "month_to_date", "total"]}

import os
for fname in os.listdir("/app/logs"):
    m = re.match(r"(\d{4}-\d{2}-\d{2})_.*\.log", fname)
    if not m:
        continue
    d = date.fromisoformat(m.group(1))
    if not (d <= today):
        continue
    periods = set()
    if d == today: periods.add("today")
    if d >= d7: periods.add("last_7_days")
    if d >= d30: periods.add("last_30_days")
    if d >= month_start: periods.add("month_to_date")
    periods.add("total")
    with open(os.path.join("/app/logs", fname)) as f:
        for line in f:
            mm = pat.search(line)
            if mm:
                s = mm.group(1)
                for p in periods:
                    counts[p][s] += 1

with open("/app/summary.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["period", "severity", "count"])
    for p in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]:
        for s in levels:
            w.writerow([p, s, counts[p][s]])
print("done")
